package com.fitforge.workout;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.ArrayList;
import java.time.LocalDateTime;
import java.time.LocalDate;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

@Service public class WorkoutService {
    private final WorkoutSessionRepository sessions;private final WorkoutSetRepository sets;private final ExerciseLibraryRepository library;private final PushUpRepository pushups;private final ExerciseGoalRepository goals;private final ObjectMapper mapper;private final CustomWorkoutExerciseRepository customExercises;private final WorkoutRoutineRepository routines;
    public WorkoutService(WorkoutSessionRepository sessions,WorkoutSetRepository sets,ExerciseLibraryRepository library,PushUpRepository pushups,ExerciseGoalRepository goals,ObjectMapper mapper,CustomWorkoutExerciseRepository customExercises,WorkoutRoutineRepository routines){this.sessions=sessions;this.sets=sets;this.library=library;this.pushups=pushups;this.goals=goals;this.mapper=mapper;this.customExercises=customExercises;this.routines=routines;}
    public List<WorkoutDtos.ExerciseGuide> library(){return library(null,null,null);}
    public List<WorkoutDtos.ExerciseGuide> library(String muscle,String search,String equipment){String m=norm(muscle),q=norm(search),eq=norm(equipment);return library.findAllByOrderByMuscleGroupAscNameAsc().stream().filter(e->m.isBlank()||contains(e.getMuscleGroup(),m)||contains(e.getPrimaryMusclesJson(),m)||contains(e.getSecondaryMusclesJson(),m)).filter(e->q.isBlank()||contains(e.getName(),q)||contains(e.getPrimaryMusclesJson(),q)||contains(e.getSecondaryMusclesJson(),q)).filter(e->eq.isBlank()||contains(e.getEquipment(),eq)).map(this::guide).toList();}
    @Transactional public WorkoutDtos.ExerciseGuide addGuide(WorkoutDtos.ExerciseGuideInput i){return guide(library.save(new ExerciseLibraryItem(i)));}
    @Transactional(readOnly=true) public List<WorkoutDtos.Session> sessions(String email){return sessions.findByUserEmailOrderBySessionDateDesc(email).stream().map(this::session).toList();}
    /** Backwards compatible: paging applies only when page or size is supplied. */
    @Transactional(readOnly=true) public List<WorkoutDtos.Session> sessions(String email,Integer page,Integer size){if(page==null&&size==null)return sessions(email);int p=page==null||page<0?0:page,s=size==null?20:Math.min(100,Math.max(1,size));return sessions.findByUserEmailOrderBySessionDateDesc(email,org.springframework.data.domain.PageRequest.of(p,s)).stream().map(this::session).toList();}
    @Transactional public WorkoutDtos.Session create(String email,WorkoutDtos.SessionInput i){return session(sessions.save(new WorkoutSession(email,i)));}
    @Transactional public WorkoutDtos.Session updateSession(String email,Long id,WorkoutDtos.SessionUpdate input){var entity=sessions.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Workout not found"));entity.update(input);return session(sessions.save(entity));}
    @Transactional public WorkoutDtos.Session duplicateSession(String email,Long id){var source=sessions.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Workout not found"));var copy=new WorkoutSession(email,new WorkoutDtos.SessionInput(source.getName()+" Copy",LocalDateTime.now()));for(var old:source.getSets()){var input=new WorkoutDtos.SetInput(old.getExerciseName(),old.getSetNumber(),old.getReps(),old.getWeightKg(),old.getPreviousWeightKg(),old.getRestSeconds(),old.getMuscleGroup(),old.getSubMuscle(),old.getEquipment(),old.getSetType(),old.getTrackingType(),old.getWeightMode(),old.getDurationSeconds(),old.getRpe(),old.getRir(),old.getNotes(),old.isCompleted());copy.addSet(new WorkoutSet(email,input,copy.getSessionDate()));}return session(sessions.save(copy));}
    @Transactional public void deleteSession(String email,Long id){var entity=sessions.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Workout not found"));sessions.delete(entity);}
    @Transactional(readOnly=true) public WorkoutDtos.Session session(String email,Long id){return session(sessions.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Workout not found")));}
    @Transactional public WorkoutDtos.SetEntry addSet(String email,Long id,WorkoutDtos.SetInput i){var s=sessions.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Workout not found"));resolveExercise(email,i);var row=new WorkoutSet(email,i,s.getSessionDate());s.addSet(row);sessions.save(s);return set(row);}
    private void resolveExercise(String email,WorkoutDtos.SetInput i){String name=i.exerciseName().trim();if(library.existsByNameIgnoreCase(name))return;if(customExercises.findByUserEmailAndNameIgnoreCaseAndDeletedFalse(email,name).isPresent())return;var existing=customExercises.findFirstByUserEmailAndNameIgnoreCaseOrderByIdDesc(email,name);if(existing.isPresent()){var row=existing.get();row.update(new WorkoutDtos.CustomExerciseInput(name,i.muscleGroup()==null||i.muscleGroup().isBlank()?"General":i.muscleGroup(),i.subMuscle(),i.equipment(),List.of(),List.of(),i.trackingType(),i.notes()),json(List.of()),json(List.of()));customExercises.save(row);return;}var input=new WorkoutDtos.CustomExerciseInput(name,i.muscleGroup()==null||i.muscleGroup().isBlank()?"General":i.muscleGroup(),i.subMuscle(),i.equipment(),List.of(),List.of(),i.trackingType(),i.notes());customExercises.save(new CustomWorkoutExercise(email,input,json(List.of()),json(List.of())));}
    @Transactional public void deleteSet(String email,Long setId){var row=sets.findByIdAndUserEmail(setId,email).orElseThrow(()->new IllegalArgumentException("Set not found"));sets.delete(row);}
    @Transactional public WorkoutDtos.SetEntry updateSet(String email,Long setId,WorkoutDtos.SetInput input){var row=sets.findByIdAndUserEmail(setId,email).orElseThrow(()->new IllegalArgumentException("Set not found"));row.update(input);return set(sets.save(row));}
    @Transactional(readOnly=true) public List<WorkoutDtos.Session> history(String email,LocalDate from,LocalDate to,String muscle,String subMuscle,String equipment,String exercise){LocalDateTime start=from==null?LocalDate.of(1970,1,1).atStartOfDay():from.atStartOfDay();LocalDateTime end=(to==null?LocalDate.now().plusDays(1):to.plusDays(1)).atStartOfDay().minusNanos(1);String m=norm(muscle),sm=norm(subMuscle),eq=norm(equipment),ex=norm(exercise);return sessions.findByUserEmailAndSessionDateBetweenOrderBySessionDateDesc(email,start,end).stream().map(s->{var filtered=s.getSets().stream().filter(x->m.isBlank()||contains(x.getMuscleGroup(),m)||contains(x.getSubMuscle(),m)).filter(x->sm.isBlank()||contains(x.getSubMuscle(),sm)).filter(x->eq.isBlank()||contains(x.getEquipment(),eq)).filter(x->ex.isBlank()||contains(x.getExerciseName(),ex)).map(this::set).toList();return new WorkoutDtos.Session(s.getId(),s.getName(),s.getSessionDate(),filtered);}).filter(s->!s.sets().isEmpty()).toList();}
    @Transactional(readOnly=true) public WorkoutDtos.HistoryAnalytics historyAnalytics(String email,LocalDate from,LocalDate to){var rows=history(email,from,to,null,null,null,null);var all=rows.stream().flatMap(s->s.sets().stream()).toList();return new WorkoutDtos.HistoryAnalytics(rows.size(),all.size(),all.stream().mapToInt(WorkoutDtos.SetEntry::reps).sum(),all.stream().mapToDouble(s->s.weightKg()*s.reps()).sum(),all.stream().mapToDouble(WorkoutDtos.SetEntry::weightKg).max().orElse(0),all.stream().map(WorkoutDtos.SetEntry::exerciseName).distinct().toList().size(),from,to);}
    @Transactional(readOnly=true) public List<WorkoutDtos.CustomExercise> customExercises(String email){return customExercises.findByUserEmailAndDeletedFalseOrderByMuscleGroupAscNameAsc(email).stream().map(this::customExercise).toList();}
    @Transactional public WorkoutDtos.CustomExercise saveCustomExercise(String email,WorkoutDtos.CustomExerciseInput input){
        String trimmedName=input.name().trim();
        var active=customExercises.findByUserEmailAndNameIgnoreCaseAndDeletedFalse(email,trimmedName);
        if(active.isPresent()){
            var row=active.get();
            row.update(input,json(input.primaryMuscles()),json(input.secondaryMuscles()));
            return customExercise(customExercises.save(row));
        }
        var created=new CustomWorkoutExercise(email,input,json(input.primaryMuscles()),json(input.secondaryMuscles()));
        return customExercise(customExercises.save(created));
    }
    @Transactional public WorkoutDtos.CustomExercise updateCustomExercise(String email,Long id,WorkoutDtos.CustomExerciseInput input){var row=customExercises.findByIdAndUserEmail(id,email).filter(x->!x.isDeleted()).orElseThrow(()->new IllegalArgumentException("Custom exercise not found"));row.update(input,json(input.primaryMuscles()),json(input.secondaryMuscles()));return customExercise(customExercises.save(row));}
    @Transactional public WorkoutDtos.CustomExercise duplicateCustomExercise(String email,Long id){var old=customExercises.findByIdAndUserEmail(id,email).filter(x->!x.isDeleted()).orElseThrow(()->new IllegalArgumentException("Custom exercise not found"));String copy=old.getName()+" Copy";int n=2;while(customExercises.existsByUserEmailAndNameIgnoreCaseAndDeletedFalse(email,copy))copy=old.getName()+" Copy "+(n++);var input=new WorkoutDtos.CustomExerciseInput(copy,old.getMuscleGroup(),old.getSubMuscle(),old.getEquipment(),list(old.getPrimaryMusclesJson()),list(old.getSecondaryMusclesJson()),old.getTrackingType(),old.getNotes());return customExercise(customExercises.save(new CustomWorkoutExercise(email,input,json(input.primaryMuscles()),json(input.secondaryMuscles()))));}
    @Transactional public void deleteCustomExercise(String email,Long id){var row=customExercises.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Custom exercise not found"));row.softDelete();}
    @Transactional(readOnly=true) public List<WorkoutDtos.Routine> routines(String email){return routines.findByUserEmailAndDeletedFalseOrderByNameAsc(email).stream().map(this::routine).toList();}
    @Transactional public WorkoutDtos.Routine saveRoutine(String email,WorkoutDtos.RoutineInput input){
        String trimmedName=input.name().trim();
        var active=routines.findByUserEmailAndNameIgnoreCaseAndDeletedFalse(email,trimmedName);
        if(active.isPresent()){
            var row=active.get();
            row.update(input,json(input.exercises()));
            return routine(routines.save(row));
        }
        var row=new WorkoutRoutine(email,input,json(input.exercises()));
        return routine(routines.save(row));
    }
    @Transactional public WorkoutDtos.Routine updateRoutine(String email,Long id,WorkoutDtos.RoutineInput input){var row=routines.findByIdAndUserEmail(id,email).filter(x->!x.isDeleted()).orElseThrow(()->new IllegalArgumentException("Routine not found"));row.update(input,json(input.exercises()));return routine(routines.save(row));}
    @Transactional public WorkoutDtos.Routine duplicateRoutine(String email,Long id){var old=routines.findByIdAndUserEmail(id,email).filter(x->!x.isDeleted()).orElseThrow(()->new IllegalArgumentException("Routine not found"));var in=new WorkoutDtos.RoutineInput(old.getName()+" Copy",old.getSplit(),old.isHomeWorkout(),routineExercises(old.getExercisesJson()));return routine(routines.save(new WorkoutRoutine(email,in,json(in.exercises()))));}
    @Transactional public void deleteRoutine(String email,Long id){var row=routines.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Routine not found"));row.softDelete();}
    public List<WorkoutDtos.SetEntry> lastSets(String email,String exercise){return sets.lastSets(email,exercise).stream().map(this::set).toList();}
    public List<WorkoutDtos.SetEntry> lastSets(String email,String exercise,String equipment){return (equipment==null||equipment.isBlank()?sets.lastSets(email,exercise):sets.lastSetsByEquipment(email,exercise,equipment)).stream().map(this::set).toList();}
    @Transactional public WorkoutDtos.RepeatResult repeat(String email,Long id,String exercise){var target=sessions.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Workout not found"));var prior=sets.lastSets(email,exercise);if(prior.isEmpty())throw new IllegalArgumentException("No previous sets found for exercise");for(var old:prior){target.addSet(new WorkoutSet(email,new WorkoutDtos.SetInput(old.getExerciseName(),old.getSetNumber(),old.getReps(),old.getWeightKg(),old.getWeightKg(),old.getRestSeconds()),target.getSessionDate()));}sessions.save(target);return new WorkoutDtos.RepeatResult(exercise,prior.size(),target.getSets().stream().filter(s->s.getExerciseName().equalsIgnoreCase(exercise)).map(this::set).toList());}
    @Transactional public WorkoutDtos.PushUp addPushUp(String email,WorkoutDtos.PushUpInput i){return pushup(pushups.save(new PushUpLog(email,i)));}
    public List<WorkoutDtos.PushUp> pushups(String email){return pushups.findByUserEmailOrderByPerformedAtDesc(email).stream().map(this::pushup).toList();}
    public List<WorkoutDtos.PersonalRecord> prs(String email){var best=new LinkedHashMap<String,WorkoutSet>();for(var row:sets.findByUserEmailOrderByExerciseNameAscWeightKgDescWorkoutDateDesc(email)){if(!row.isCompleted()||row.getWeightKg()<=0||row.getWeightKg()>500||"WARMUP".equalsIgnoreCase(row.getSetType())||"W".equalsIgnoreCase(row.getSetType()))continue;best.putIfAbsent(row.getExerciseName().toLowerCase(java.util.Locale.ROOT),row);}return best.values().stream().map(s->new WorkoutDtos.PersonalRecord(s.getExerciseName(),s.getWeightKg(),s.getReps(),s.getWorkoutDate())).toList();}
    @Transactional public WorkoutDtos.ExerciseProgress putGoal(String email,WorkoutDtos.ExerciseGoalInput i){var goal=goals.findByUserEmailAndExerciseNameIgnoreCase(email,i.exerciseName()).orElseGet(()->new ExerciseGoal(email,i));goal.update(i);return progress(goal);}
    @Transactional(readOnly=true) public List<WorkoutDtos.ExerciseProgress> goals(String email){return goals.findByUserEmailAndDeletedFalseOrderByExerciseNameAsc(email).stream().map(this::progress).toList();}
    @Transactional public void deleteGoal(String email,String exerciseName){var goal=goals.findByUserEmailAndExerciseNameIgnoreCase(email,exerciseName).orElseThrow(()->new IllegalArgumentException("Exercise goal not found"));if(goal.isDeleted())return;goal.softDelete();goals.save(goal);}
    private WorkoutDtos.ExerciseProgress progress(ExerciseGoal goal){var rows=sets.sessionsForExercise(goal.getUserEmail(),goal.getExerciseName());var grouped=new LinkedHashMap<LocalDateTime,List<WorkoutSet>>();for(var row:rows)grouped.computeIfAbsent(row.getWorkoutDate(),k->new ArrayList<>()).add(row);var sessions=new ArrayList<>(grouped.values());Metric current=sessions.isEmpty()?Metric.EMPTY:metric(sessions.get(0));Metric previous=sessions.size()<2?Metric.EMPTY:metric(sessions.get(1));int stagnant=0;for(int i=0;i<sessions.size()-1;i++){Metric newer=metric(sessions.get(i)),older=metric(sessions.get(i+1));if(newer.weight<=older.weight&&newer.reps<=older.reps&&newer.volume<=older.volume)stagnant++;else break;}boolean met=sessions.stream().findFirst().orElse(List.of()).stream().anyMatch(s->s.getWeightKg()>=goal.getTargetWeightKg()&&s.getReps()>=goal.getTargetReps());boolean missed=LocalDate.now().isAfter(goal.getDeadlineDate())&&!met;long late=missed?java.time.temporal.ChronoUnit.DAYS.between(goal.getDeadlineDate(),LocalDate.now()):0;boolean plateau=stagnant>=2;String advice=plateau?"Plateau across at least 2 sessions: review technique, sleep and load; consider a light deload week before progressing.":missed?"Target deadline passed; revise the target or deadline based on current logs. Do not force jumps in load.":"Keep form consistent and increase load only after all prescribed reps are achieved cleanly.";return new WorkoutDtos.ExerciseProgress(goal.getId(),goal.getExerciseName(),goal.getTargetWeightKg(),goal.getTargetReps(),goal.getDeadlineDate(),previous.weight,previous.reps,previous.volume,current.weight,current.reps,current.volume,stagnant,plateau,met,missed,late,advice);}
    private Metric metric(List<WorkoutSet> rows){double weight=rows.stream().mapToDouble(WorkoutSet::getWeightKg).max().orElse(0),volume=rows.stream().mapToDouble(s->s.getWeightKg()*s.getReps()).sum();int reps=rows.stream().mapToInt(WorkoutSet::getReps).max().orElse(0);return new Metric(weight,reps,volume);}
    private record Metric(double weight,int reps,double volume){static final Metric EMPTY=new Metric(0,0,0);}
    private WorkoutDtos.ExerciseGuide guide(ExerciseLibraryItem e){return new WorkoutDtos.ExerciseGuide(e.getId(),e.getName(),e.getMuscleGroup(),e.getEquipment(),e.getSetup(),e.getBrace(),e.getExecution(),e.getCommonMistakes(),list(e.getPrimaryMusclesJson()),list(e.getSecondaryMusclesJson()),e.getLevel(),list(e.getInstructionsJson()),list(e.getImageUrlsJson()),e.getSource());}
    private List<String> list(String s){try{return s==null?List.of():mapper.readValue(s,new TypeReference<List<String>>(){});}catch(Exception e){return List.of();}}
    private boolean contains(String value,String q){return value!=null&&value.toLowerCase(java.util.Locale.ROOT).contains(q);}
    private String norm(String s){return s==null?"":s.trim().toLowerCase(java.util.Locale.ROOT);}
    private WorkoutDtos.Session session(WorkoutSession e){return new WorkoutDtos.Session(e.getId(),e.getName(),e.getSessionDate(),e.getSets().stream().map(this::set).toList());}
    private WorkoutDtos.SetEntry set(WorkoutSet e){return new WorkoutDtos.SetEntry(e.getId(),e.getExerciseName(),e.getSetNumber(),e.getReps(),e.getWeightKg(),e.getPreviousWeightKg(),e.getDeltaKg(),e.getRestSeconds(),e.getWorkoutDate(),e.getTrackingType(),e.getWeightMode(),e.getMuscleGroup(),e.getSubMuscle(),e.getEquipment(),e.getSetType(),e.getDurationSeconds(),e.getRpe(),e.getRir(),e.getNotes(),e.isCompleted());}
    private WorkoutDtos.CustomExercise customExercise(CustomWorkoutExercise e){return new WorkoutDtos.CustomExercise(e.getId(),e.getName(),e.getMuscleGroup(),e.getSubMuscle(),e.getEquipment(),list(e.getPrimaryMusclesJson()),list(e.getSecondaryMusclesJson()),e.getTrackingType(),e.getNotes());}
    private WorkoutDtos.Routine routine(WorkoutRoutine e){return new WorkoutDtos.Routine(e.getId(),e.getName(),e.getSplit(),e.isHomeWorkout(),routineExercises(e.getExercisesJson()));}
    private List<WorkoutDtos.RoutineExercise> routineExercises(String value){try{return value==null?List.of():mapper.readValue(value,new TypeReference<List<WorkoutDtos.RoutineExercise>>(){});}catch(Exception ex){return List.of();}}
    private String json(Object value){try{return mapper.writeValueAsString(value==null?List.of():value);}catch(Exception ex){throw new IllegalArgumentException("Invalid workout data");}}
    private WorkoutDtos.PushUp pushup(PushUpLog e){return new WorkoutDtos.PushUp(e.getId(),e.getRepetitions(),e.getVariation(),e.getDurationSeconds(),e.getPerformedAt(),e.getNotes());}
}
